{
  "name": "SHFQA量子分析仪",
  "name_en": "SHFQA Quantum Analyzer",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台用于量子测量的射频/微波量子分析仪，证据显示其支持示波采集、QA通道配置、序列器程序加载、波形写入、读出积分权重设置、结果记录以及多能级量子态读出等功能，常用于超导量子比特实验中的激励与读出测量。",
  "description_en": "This is an RF/microwave quantum analyzer for quantum measurements. The evidence shows support for scope acquisition, QA channel configuration, sequencer program loading, waveform transfer, readout integration weights, result logging, and multi-state qudit readout, as commonly used in superconducting qubit excitation and readout experiments.",
  "tag_hints": [
    "quantum readout",
    "superconducting qubits",
    "microwave pulse sequencing",
    "scope acquisition",
    "integration weights",
    "result logger",
    "qudit discrimination",
    "SHFQA"
  ],
  "actions": [
    {
      "action_name": "auto-configure",
      "description": "配置示波器测量参数。",
      "description_en": "Configure the scope for a measurement."
    },
    {
      "action_name": "auto-read",
      "description": "读取示波器记录的数据。",
      "description_en": "Read the recorded scope data."
    },
    {
      "action_name": "auto-run",
      "description": "启动示波器采集。",
      "description_en": "Start the scope recording."
    },
    {
      "action_name": "auto-stop",
      "description": "停止示波器采集。",
      "description_en": "Stop the scope recording."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待示波器采集完成。",
      "description_en": "Wait until the scope recording is finished."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用序列器。",
      "description_en": "Enable the sequencer."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译序列器程序。",
      "description_en": "Compile the sequencer program."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "加载序列器程序到仪器。",
      "description_en": "Load a sequencer program to the instrument."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "将波形写入波形存储器。",
      "description_en": "Write waveforms to waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从波形存储器读取波形。",
      "description_en": "Read waveforms from waveform memory."
    },
    {
      "action_name": "auto-configure_sequencer_triggering",
      "description": "配置序列器触发方式。",
      "description_en": "Configure sequencer triggering."
    },
    {
      "action_name": "auto-available_aux_trigger_inputs",
      "description": "获取可用辅助触发输入。",
      "description_en": "Get available auxiliary trigger inputs."
    },
    {
      "action_name": "auto-get_qudits_results",
      "description": "获取多能级量子态读出结果。",
      "description_en": "Get qudit readout results."
    },
    {
      "action_name": "auto-configure_result_logger",
      "description": "配置结果记录器。",
      "description_en": "Configure the result logger."
    },
    {
      "action_name": "auto-write_integration_weights",
      "description": "写入读出积分权重。",
      "description_en": "Write readout integration weights."
    },
    {
      "action_name": "auto-read_integration_weights",
      "description": "读取读出积分权重。",
      "description_en": "Read readout integration weights."
    },
    {
      "action_name": "auto-configure_channel",
      "description": "配置QA通道参数。",
      "description_en": "Configure a QA channel."
    },
    {
      "action_name": "auto-available_trigger_inputs",
      "description": "获取可用触发输入。",
      "description_en": "Get available trigger inputs."
    },
    {
      "action_name": "auto-available_inputs",
      "description": "获取可用信号输入。",
      "description_en": "Get available signal inputs."
    },
    {
      "action_name": "auto-factory_reset",
      "description": "将仪器恢复为出厂默认设置。",
      "description_en": "Reset the instrument to factory defaults."
    },
    {
      "action_name": "auto-start_continuous_sw_trigger",
      "description": "启动连续软件触发。",
      "description_en": "Start continuous software triggering."
    },
    {
      "action_name": "auto-max_qubits_per_channel",
      "description": "获取每个通道支持的最大量子比特数。",
      "description_en": "Get the maximum qubits per channel."
    }
  ]
}

